// Vault schema and connection, on SQLite via `node:sqlite` (built into Node 24).
//
// No ORM and no migration framework: the `CREATE TABLE IF NOT EXISTS` below is
// the whole schema and runs on every open. When a column has to change, this
// is where the migration lives.
//
// Three decisions the rest of the system relies on:
//   * the primary key of bookmarks is (user_id, id), where `id` is a UUID
//     generated by the client, which is what allows creating one offline;
//   * deleting is `deleted = 1` (a tombstone), never DELETE, otherwise the
//     other client would never learn that the record is gone;
//   * a folder is a path, in `bookmarks.folder` and in `folders.path` alike.
//     One bookmark is in one folder; the same URL saved in two folders is two
//     records, which is allowed and never deduplicated.
'use strict';

const { DatabaseSync } = require('node:sqlite');
const path = require('node:path');
const fs = require('node:fs');
const os = require('node:os');

function defaultDbPath() {
  if (process.env.BOOKMARKS_DB) return process.env.BOOKMARKS_DB;
  const base = process.env.XDG_DATA_HOME || path.join(os.homedir(), '.local', 'share');
  return path.join(base, 'bookmarks', 'bookmarks.db');
}

// The field used to be called `notes`. Databases created before the rename get
// the column renamed on open: the CREATE TABLE above does not run on a table
// that already exists, so without this an old vault would lose the text.
function migrateNotesToDescription(db) {
  const columns = db.prepare('SELECT name FROM pragma_table_info(?)').all('bookmarks').map((c) => c.name);
  if (columns.includes('description') || !columns.includes('notes')) return;
  db.exec('ALTER TABLE bookmarks RENAME COLUMN notes TO description');
}

// Vaults created before usage ranking have no counters. The CREATE TABLE above
// does not run on an existing table, so the columns are added here.
function addUsageColumns(db) {
  const columns = db.prepare('SELECT name FROM pragma_table_info(?)').all('bookmarks').map((c) => c.name);
  if (!columns.includes('opens')) db.exec('ALTER TABLE bookmarks ADD COLUMN opens INTEGER NOT NULL DEFAULT 0');
  if (!columns.includes('last_open_at')) db.exec('ALTER TABLE bookmarks ADD COLUMN last_open_at INTEGER NOT NULL DEFAULT 0');
}

function open(dbPath = defaultDbPath()) {
  if (dbPath !== ':memory:') fs.mkdirSync(path.dirname(dbPath), { recursive: true });

  const db = new DatabaseSync(dbPath);
  db.exec('PRAGMA journal_mode = WAL');
  db.exec('PRAGMA foreign_keys = ON');

  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id         INTEGER PRIMARY KEY AUTOINCREMENT,
      email      TEXT NOT NULL UNIQUE,
      username   TEXT NOT NULL UNIQUE,
      pass_hash  TEXT NOT NULL,
      created_at INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS sessions (
      token      TEXT PRIMARY KEY,
      user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      created_at INTEGER NOT NULL
    );

    -- id is a client-generated UUID, which is what allows offline creation.
    CREATE TABLE IF NOT EXISTS bookmarks (
      id         TEXT NOT NULL,
      user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      title      TEXT NOT NULL DEFAULT '',
      url        TEXT NOT NULL DEFAULT '',
      folder     TEXT NOT NULL DEFAULT '',
      category   TEXT NOT NULL DEFAULT '',
      tags       TEXT NOT NULL DEFAULT '',
      description      TEXT NOT NULL DEFAULT '',
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      deleted    INTEGER NOT NULL DEFAULT 0,
      -- How often this bookmark was opened, and when it was last opened. Both
      -- only ever grow: clients merge them with MAX, never with last-write-wins,
      -- so a count is not lost when two devices open the same link offline.
      opens        INTEGER NOT NULL DEFAULT 0,
      last_open_at INTEGER NOT NULL DEFAULT 0,
      PRIMARY KEY (user_id, id)
    );

    CREATE INDEX IF NOT EXISTS idx_bm_sync ON bookmarks(user_id, updated_at);

    -- A folder exists in two ways: derived from the folder string of a
    -- bookmark, or created on its own. Only the second kind lives here, and
    -- that is what lets an empty folder survive a reload. The tree the app
    -- draws is the union of the two, so a folder that only exists because
    -- something is inside it still disappears when it empties, as it always did.
    --
    -- The key is the path and not a UUID, because the path already is the
    -- identity of a folder everywhere else: the folder column above, the
    -- /dev token of the search. An id with a parent_id alongside those
    -- strings would be a second source of truth, free to disagree with them.
    CREATE TABLE IF NOT EXISTS folders (
      user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      path       TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      -- A tombstone, for the same reason a bookmark has one: the other client
      -- would never learn that the folder is gone.
      deleted    INTEGER NOT NULL DEFAULT 0,
      PRIMARY KEY (user_id, path)
    );

    CREATE INDEX IF NOT EXISTS idx_folder_sync ON folders(user_id, updated_at);

    -- One row per open, which is what the opens counter cannot tell you: when
    -- it happened. This is what the insights screen reads, and it is pruned on
    -- write, so it stays a recent history and not a permanent record.
    CREATE TABLE IF NOT EXISTS opens_log (
      id          INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id     INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      bookmark_id TEXT NOT NULL,
      at          INTEGER NOT NULL
    );

    CREATE INDEX IF NOT EXISTS idx_opens_when ON opens_log(user_id, at);
  `);

  migrateNotesToDescription(db);
  addUsageColumns(db);
  return db;
}

module.exports = { open, defaultDbPath };
